"def test_claim_users_with_mixed_input(enterprise, enterprise_mocks):
    users = {
        'usrFakeUserId1': 'managed',
        'someone@example.com': 'unmanaged',
        'usrFakeUserId2': 'managed',
        'another@example.com': 'managed'
    }
    result = enterprise.claim_users(users)

    assert isinstance(result, ManageUsersResponse)
    assert enterprise_mocks.claim_users.call_count == 1

    expected_payload = {
        'users': [
            {'id': 'usrFakeUserId1', 'state': 'managed'},
            {'email': 'someone@example.com', 'state': 'unmanaged'},
            {'id': 'usrFakeUserId2', 'state': 'managed'},
            {'email': 'another@example.com', 'state': 'managed'}
        ]
    }
    assert enterprise_mocks.claim_users.last_request.json() == expected_payload"

"import pytest
from unittest.mock import Mock

def test_users_with_mixed_inputs_and_collaborations(enterprise, monkeypatch):
    mock_api_get = Mock()
    mock_api_get.return_value = {
        "users": [
            {
                "id": "usrL2PNC5o3H4lBEi",
                "email": "user1@example.com",
                "name": "User One",
                "state": "provisioned",
                "isSsoRequired": False,
                "isTwoFactorAuthEnabled": True
            },
            {
                "id": "usrA1B2C3D4E5F6G7",
                "email": "user2@example.com",
                "name": "User Two",
                "state": "provisioned",
                "isSsoRequired": True,
                "isTwoFactorAuthEnabled": False
            }
        ]
    }
    monkeypatch.setattr(enterprise.api, 'get', mock_api_get)

    search_for = ["usrL2PNC5o3H4lBEi", "user2@example.com"]
    results = enterprise.users(search_for, collaborations=True)

    assert len(results) == 2
    assert all(isinstance(user, UserInfo) for user in results)
    assert {user.id for user in results} == {"usrL2PNC5o3H4lBEi", "usrA1B2C3D4E5F6G7"}
    assert {user.name for user in results} == {"User One", "User Two"}
    assert {user.email for user in results} == {"user1@example.com", "user2@example.com"}

    mock_api_get.assert_called_once_with(
        url=f"{enterprise.url}/users",
        params={
            "id": ["usrL2PNC5o3H4lBEi"],
            "email": ["user2@example.com"],
            "include": ["collaborations"]
        }
    )"

"@pytest.mark.parametrize('django_version', [(4, 0), (3, 2), (1, 11), None])
@pytest.mark.parametrize('django_redis_installed', [True, False])
def test_rediscache_compat_with_django_versions(django_version, django_redis_installed):
    django_new = 'django.core.cache.backends.redis.RedisCache'
    redis_cache = 'redis_cache.RedisCache'
    django_redis = 'django_redis.cache.RedisCache'
    with mock.patch.object(environ.compat, 'DJANGO_VERSION', django_version):
        with mock.patch('environ.compat.find_spec') as mock_find_spec:
            mock_find_spec.return_value = django_redis_installed
            driver = environ.compat.choose_rediscache_driver()

            if django_redis_installed:
                assert driver == django_redis
            elif django_version and django_version >= (4, 0):
                assert driver == django_new
            elif django_version and django_version < (2, 0):
                assert driver == django_new
            else:
                assert driver == redis_cache"

"from unittest.mock import patch

def test_users_with_mixed_inputs_and_collaborations(enterprise):
    mock_api_response = {
        'users': [
            {
                'id': 'usr1',
                'email': 'user1@example.com',
                'name': 'User One',
                'state': 'active',
                'isSsoRequired': False,
                'isTwoFactorAuthEnabled': True
            },
            {
                'id': 'usr2',
                'email': 'user2@example.com',
                'name': 'User Two',
                'state': 'provisioned',
                'isSsoRequired': True,
                'isTwoFactorAuthEnabled': False
            },
        ]
    }

    with patch.object(enterprise.api, 'get', return_value=mock_api_response) as mock_api_get:
        ids_or_emails = ['usr1', 'user2@example.com', 'usr3']
        results = enterprise.users(ids_or_emails, collaborations=True)

        assert len(results) == 2
        assert all(isinstance(user, UserInfo) for user in results)
        assert {user.id for user in results} == {'usr1', 'usr2'}
        assert {user.email for user in results} == {'user1@example.com', 'user2@example.com'}
        assert {user.name for user in results} == {'User One', 'User Two'}
        assert {user.state for user in results} == {'active', 'provisioned'}

        mock_api_get.assert_called_once_with(
            url=f'{enterprise.url}/users',
            params={'id': ['usr1', 'usr3'], 'email': ['user2@example.com'], 'include': ['collaborations']}
        )"

"def test_options_to_json_and_params_with_new_features():
    options = {
        'fields': ['Name', 'Phone', 'Name'],  # Duplicate field
        'max_records': 0,  # Should be removed
        'sort': ['Name', '-Age'],
        'use_field_ids': 1,
        'user_locale': 'en-US',
        'time_zone': 'America/New_York'
    }

    expected_json = {
        'fields': ['Name', 'Phone'],  # Duplicates removed
        'sort': [
            {'field': 'Name', 'direction': 'asc'},
            {'field': 'Age', 'direction': 'desc'}
        ],
        'returnFieldsByFieldId': True
    }

    expected_params = {
        'userLocale': 'en-US',
        'timeZone': 'America/New_York'
    }

    result_json, result_params = options_to_json_and_params(options)

    assert result_json == expected_json
    assert result_params == expected_params"

"import netrc
from requests.auth import HTTPBasicAuth
from scrapyd_client.utils import get_auth

@pytest.mark.parametrize('url,username,password,expected', [
    ('http://localhost:6800', 'user', 'pass', HTTPBasicAuth('user', 'pass')),
    ('http://localhost:6800', 'user', None, None),
    ('http://localhost:6800', None, 'pass', None),
    ('http://example.com', None, None, HTTPBasicAuth('netrc_user', 'netrc_pass')),
    ('', None, None, None),
])
def test_get_auth_with_changes(url, username, password, expected, monkeypatch):
    def mock_netrc():
        class MockNetrc:
            def authenticators(self, host):
                return ('netrc_user', None, 'netrc_pass') if host == 'example.com' else None
        return MockNetrc()

    monkeypatch.setattr(netrc, 'netrc', mock_netrc)

    result = get_auth(url, username, password)

    if expected is None:
        assert result is None
    else:
        assert isinstance(result, HTTPBasicAuth)
        assert result.username == expected.username
        assert result.password == expected.password"
